const mcq = (item: {
  id: string; slug: string; title: string; question: string; unit?: number; topic: string; category?: string;
  correct: { id: string; text: string; rationale: string; structure: string };
  distractors: Array<{ id: string; text: string; rationale: string; structure: string }>;
}) => {
  const options = [item.correct, ...item.distractors].map(option => ({
    id: option.id, text: option.text, structureId: option.structure,
    explanation: option.rationale, isCorrect: option.id === item.correct.id
  }));
  return {
    id: item.id, slug: item.slug, title: item.title, level: 1 as const, difficulty: 'Easy',
    category: item.category || (item.unit ? `Unit ${item.unit}` : 'Supplementary'),
    ...(item.unit ? { syllabusUnit: item.unit } : {}), syllabusTopic: item.topic,
    missionBrief: item.question, question: item.question, options,
    requirements: [{ id: 'r1', label: item.topic, description: item.question, critical: true, satisfiedBy: [item.correct.structure] }],
    availableStructures: [...new Set(options.map(option => option.structureId))],
    optimalStructures: [item.correct.structure], rewardXp: 100
  };
};

const scenario = (item: {
  id: string; slug: string; title: string; question: string; unit?: number; topic: string; category?: string;
  choices: string[]; answer: string; explanation: string; distractorExplanations: Record<string, string>;
}) => ({
  id: item.id, slug: item.slug, title: item.title, level: 2 as const, difficulty: 'Medium',
  category: item.category || (item.unit ? `Unit ${item.unit}` : 'Supplementary'),
  ...(item.unit ? { syllabusUnit: item.unit } : {}), syllabusTopic: item.topic,
  missionBrief: item.question, question: item.question,
  availableStructures: item.choices, optimalStructures: [item.answer], rewardXp: 150,
  requirements: [{ id: 'r1', label: item.topic, description: item.question, critical: true, satisfiedBy: [item.answer] }],
  comparisonCriteria: item.choices.map(choice => ({
    criterion: item.topic, description: item.distractorExplanations[choice] || item.explanation,
    bestChoice: choice, explanation: choice === item.answer ? item.explanation : item.distractorExplanations[choice] || 'This choice does not meet the stated constraint.'
  }))
});

const hybrid = (item: {
  id: string; slug: string; title: string; question: string; unit?: number; topic: string; category?: string;
  choices: string[]; requirements: Array<{ id: string; label: string; description: string; critical: boolean; satisfiedBy: string[] }>;
  answer: string[]; explanation: string; level: 3 | 4;
}) => ({
  id: item.id, slug: item.slug, title: item.title, level: item.level,
  difficulty: item.level === 3 ? 'Hard' : 'Expert', category: item.category || (item.unit ? `Unit ${item.unit}` : 'Supplementary'),
  ...(item.unit ? { syllabusUnit: item.unit } : {}), syllabusTopic: item.topic, missionBrief: item.question, question: item.question,
  requirements: item.requirements, availableStructures: item.choices, optimalStructures: item.answer,
  rewardXp: item.level === 3 ? 250 : 400,
  comparisonCriteria: [{ criterion: item.topic, description: item.explanation, bestChoice: item.answer[0], explanation: item.explanation }]
});

